class NomTipoConceptoPD extends BaseNomTipoConceptoPD {

    /**
     * Obtener un listado de los datos de los tipos de conceptos de percepcion y descuento.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de conceptos de percepcion y descuento.
     */
    public static function obtenerListadoTiposConceptoPD($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de los tipos de conceptos de percepcion y descuento en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomTipoConceptoPD')
				->orderBy('denominacion')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray():
                $query->from('NomTipoConceptoPD')
				->orderBy('denominacion')
                ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de tipos de conceptos de percepcion y descuento.
     * 
     * @return int      Cantidad total de tipos de conceptos de percepcion y descuento.
     */
    public static function obtenerCantidadTotalTiposConceptoPD() {

        //Devolviendo la cantidad total de tipos de conceptos de percepcion y descuento.
        return Doctrine_Query::create()->select('COUNT(idtipoconceptopd) AS cantidad')
                        ->from('NomTipoConceptoPD')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el tipo de concepto de percepcion y descuento dado el identificador.
     * 
     * @param $idtconcep            Identificador del tipo de concepto de percepcion y descuento.
     * @return NomTipoConceptoPD    Objeto tipo de concepto de percepcion y descuento (clase del dominio).
     */
    public static function obtenerObjTipoConceptoPDDadoId($idtconcep) {
        return Doctrine::getTable('NomTipoConceptoPD')->find($idtconcep);
    }

    /**
     * Obtener todos los tipos de conceptos.
     * 
     * @return array    Listado de los datos de los tipos de conceptos.
     */
    public static function obtenerTodosTiposConceptosPD() {

        //Devolviendo el listado de los tipos de conceptos en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTipoConceptoPD')
				->orderBy('denominacion')
                ->fetchArray();
    }
	
	/**
     * Obtener si existe el tipo de concepto de pd a partir de la denominaci�n.
     * 
	 * @param int $idtipo    		Identificador del tipo de concepto de pd.
     * @param string $denom    	 	Denominaci�n del tipo de concepto de pd.
	 *
     * @return boolean    			Si existe el tipo de concepto de pd.
     */
    public static function existeTipoConceptoPD($idtipo, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idtipoconceptopd) AS cantidad')
                        ->from('NomTipoConceptoPD')
						->where("denominacion ilike ?", $denom);
		if($idtipo){
			$query->addWhere('idtipoconceptopd <> ?', $idtipo);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
 /**********************************VER DESDE AQUI*************************************************/   
    public static function obtenerDenomXId($idtipoconcepto) {
        return Doctrine_Query::create()->select('p.denominacion AS denominacion')
                        ->from('NomTipoConceptoPD p')
                        ->where('p.idtipoconceptopd = ?', array($idtipoconcepto))
                        ->fetchOne()
                        ->denominacion;
   }
   
   public static function existeDenominacionTipoConceptoPD($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTipoConceptoPD p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }


    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idtipoconceptopd = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomTipoConceptoPD')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idtipoconceptopd)) {
                $query->andWhere("idtipoconceptopd <> ?", $idtipoconceptopd);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }
}
